#!/bin/sh
# Guard: the engine's src/ is Gleam and nothing else.
#
# *"No handwritten erlangs or even worse JS source files, keep the system
# clean and beautiful!"* [user 2026-11-07]
# *"target erlang 无需手写任何erlang代码，无需ffi，ffi是JS专属的"*
# [user 2026-11-01, glib RULINGS.md §1.28]
#
# Since Gleam v1.19.0 (2026-10-05) modules compile to Erlang abstract forms
# (.abstr) then .beam, with no .erl per module. The one @@main.erl inside
# build/ is the `gleam run` runner stub, still generated by 1.19.2 -- not
# compiled module code and not a leftover from an older compiler.
# A .mjs/.js under src/ means someone escaped Gleam again. This guard is the
# mechanism that makes the ruling fail loudly instead of decaying into prose.
#
# Scope: the root src/ — the Erlang-target engine. `deprecated/glibe_web` is
# the old Phoenix app, kept for comparison and not part of this build.
#
# The JavaScript-target client is a SEPARATE package in `webclient/`, with its
# own gleam.toml declaring `target = "javascript"`. Gleam source there compiles
# to .mjs; a hand-written .mjs is allowed only inside that folder. The target
# boundary is declared by the two packages themselves, so this guard only has
# to keep the engine's src/ clean — it does not police the client's layout.
# `*.disabled` files are retired design records, not compiled source.
#
# R15 [user 2026-11-07]: IB is scoped to historic data for stocks/ETFs, and
# *"if this will cause JS target dependence, I would rather give up ib
# entirely"*. A javascript external is exactly that dependence, so fail here
# rather than discovering it at the broker boundary.

set -e
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$ROOT"

found="$(
  find src -type f \( \
    -name '*.erl' -o -name '*.hrl' -o -name '*.ex' -o -name '*.exs' \
    -o -name '*.mjs' -o -name '*.js' -o -name '*.ts' \
  \) -print
)"

if [ -n "$found" ]; then
  echo "no_foreign_source: handwritten foreign source under src/:" >&2
  echo "$found" >&2
  echo "Write it in Gleam. BEAM needs no FFI file from your hand." >&2
  exit 1
fi

js_externals="$(
  find src -type f -name '*.gleam' -exec grep -Hn '@external(javascript' {} + 2>/dev/null || true
)"
if [ -n "$js_externals" ]; then
  echo "no_foreign_source: @external(javascript, ...) under src/:" >&2
  echo "$js_externals" >&2
  echo "Drop the feature or write it in Gleam. Erlang target only." >&2
  exit 1
fi

if grep -Eq '^target *= *"javascript"' gleam.toml; then
  echo "no_foreign_source: gleam.toml declares the javascript target" >&2
  exit 1
fi

echo "no_foreign_source: clean — src/ is Gleam only, erlang target only"
